package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for {
		line, err := r.ReadString('\n')
		if err != nil && line == "" {
			break
		}
		line = strings.TrimRight(line, "\r\n")
		var fields []string
		var cur strings.Builder
		inQ := false
		for i := 0; i < len(line); i++ {
			c := line[i]
			if inQ {
				if c == '"' {
					if i+1 < len(line) && line[i+1] == '"' {
						cur.WriteByte('"')
						i++
					} else {
						inQ = false
					}
				} else {
					cur.WriteByte(c)
				}
			} else if c == '"' {
				inQ = true
			} else if c == ',' {
				fields = append(fields, cur.String())
				cur.Reset()
			} else {
				cur.WriteByte(c)
			}
		}
		fields = append(fields, cur.String())
		fmt.Fprintf(w, "%d: ", len(fields))
		for i, f := range fields {
			if i > 0 {
				w.WriteByte('|')
			}
			w.WriteString("[" + f + "]")
		}
		w.WriteByte('\n')
		if err != nil {
			break
		}
	}
}
